import{Schema}from'../schema';import{migrateParsedSave}from'./migrations';import{extractAcuTables}from'./acuTables';import type{ParsedSaveSource,PortableSave,ResumeMessage}from'./types';
export async function parsePortableSave(file:File):Promise<ParsedSaveSource>{if(file.size>128*1024*1024)throw new Error('文件超过128 MiB限制');const raw=JSON.parse(await file.text())as PortableSave;if(raw.format!=='counterfeit-portable-save'||!Number.isInteger(raw.version)||!raw.state?.stat_data)throw new Error('不是 Counterfeit portable save');const hash=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());const sha256=[...new Uint8Array(hash)].map(v=>v.toString(16).padStart(2,'0')).join('');const rawSheets=raw.state.table_sheets;return{source:'counterfeit-export',cardVersion:raw.card_version??null,schemaVersion:raw.version,declaredCampaignId:raw.campaign_id??null,declaredCampaignRevision:Number.isInteger(raw.campaign_revision)?raw.campaign_revision:null,statData:raw.state.stat_data,resumeTail:sanitizeResumeTail(raw.resume_tail),messageCount:raw.provenance?.source_message_count??0,recoveredFloor:null,warnings:[],sha256,legacyEstablishedFacts:Array.isArray(raw.legacy_established_facts)?raw.legacy_established_facts.filter(fact=>typeof fact==='string'):[],tableSheets:rawSheets&&typeof rawSheets==='object'?JSON.parse(JSON.stringify(rawSheets)):null}}
export function sanitizeResumeTail(items:ResumeMessage[]):ResumeMessage[]{let chars=0;return(Array.isArray(items)?items:[]).slice(-8).flatMap(item=>{if(!item||!['user','assistant'].includes(item.role)||typeof item.text!=='string')return[];const text=item.text.replace(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/gi,'').replace(/<[^>]+>/g,'').replace(/data:[^\s]+/g,'[媒体已移除]').trim();if(!text||chars+text.length>12_000)return[];chars+=text.length;return[{role:item.role,text}as ResumeMessage]})}
export async function buildPortableSave(statData:unknown,resumeTail:ResumeMessage[],sourceMessageCount:number,tableSheets?:Record<string,unknown>|null):Promise<PortableSave>{const stat=Schema.parse(statData)as Record<string,any>;const safeTail=sanitizeResumeTail(resumeTail);const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify({stat,safeTail})));const source_sha256=[...new Uint8Array(digest)].map(v=>v.toString(16).padStart(2,'0')).join('');const sheets=tableSheets===undefined?extractAcuTables((typeof SillyTavern!=='undefined'?SillyTavern.chatMetadata:(window.top as any)?.SillyTavern?.chatMetadata)??null):tableSheets;return{format:'counterfeit-portable-save',version:1,exported_at:new Date().toISOString(),card_version:'0.6.0',campaign_id:stat.campaign_id,campaign_revision:stat.campaign_revision,state:{stat_data:stat,...(sheets?{table_sheets:sheets}:{})},resume_tail:safeTail,provenance:{source:'counterfeit-export',source_message_count:sourceMessageCount,source_sha256}}}export{migrateParsedSave};
